from html.parser import HTMLParser
class Text(HTMLParser):
 def handle_data(self, data):
  if any(x in data.lower() for x in ('store', 'input_text', 'output_text', 'responses', 'model')):
   print(data[:900])
p=Text(); p.feed(open('/tmp/openai-responses-doc.html').read())
PY"

